window.ScripturaLexicons.BDAG_PART_0158 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zeta-numeral-bdag\" data-source=\"BDAG\" data-search=\"ζ´ sinal numérico grego sete; sétimo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζ´</td><td>sinal numérico grego</td><td>sete; sétimo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zaboulon-bdag\" data-source=\"BDAG\" data-search=\"Ζαβουλών, ὁ nome próprio masculino indeclinável Zebulom BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ζαβουλών, ὁ</td><td>nome próprio masculino indeclinável</td><td>Zebulom</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zakchaios-bdag\" data-source=\"BDAG\" data-search=\"Ζακχαῖος, ου, ὁ nome próprio masculino Zaqueu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ζακχαῖος, ου, ὁ</td><td>nome próprio masculino</td><td>Zaqueu</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zara-bdag\" data-source=\"BDAG\" data-search=\"Ζάρα, ὁ nome próprio masculino Zerá BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ζάρα, ὁ</td><td>nome próprio masculino</td><td>Zerá</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zaphthani-bdag\" data-source=\"BDAG\" data-search=\"ζαφθάνι forma textual aramaica transliterada variante textual de σαβαχθάνι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζαφθάνι</td><td>forma textual aramaica transliterada</td><td>variante textual de σαβαχθάνι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zacharias-bdag\" data-source=\"BDAG\" data-search=\"Ζαχαρίας, ου, ὁ nome próprio masculino Zacarias BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ζαχαρίας, ου, ὁ</td><td>nome próprio masculino</td><td>Zacarias</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zao-bdag\" data-source=\"BDAG\" data-search=\"[ζάω] verbo viver; estar vivo; comportar-se; ser vivaz; oferecer vida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">[ζάω]</td><td>verbo</td><td>viver; estar vivo; comportar-se; ser vivaz; oferecer vida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zbennymi-bdag\" data-source=\"BDAG\" data-search=\"ζβέννυμι verbo remissivo ver σβέννυμι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζβέννυμι</td><td>verbo remissivo</td><td>ver σβέννυμι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zebedaios-bdag\" data-source=\"BDAG\" data-search=\"Ζεβεδαῖος, ου, ὁ nome próprio masculino Zebedeu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ζεβεδαῖος, ου, ὁ</td><td>nome próprio masculino</td><td>Zebedeu</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zestos-bdag\" data-source=\"BDAG\" data-search=\"ζεστός, ή, όν adjetivo quente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζεστός, ή, όν</td><td>adjetivo</td><td>quente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zeugnymi-bdag\" data-source=\"BDAG\" data-search=\"ζεύγνυμι verbo ligar; unir sob um jugo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζεύγνυμι</td><td>verbo</td><td>ligar; unir sob um jugo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zeugos-bdag\" data-source=\"BDAG\" data-search=\"ζεῦγος, ους, τό substantivo neutro junta; parelha; par BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζεῦγος, ους, τό</td><td>substantivo neutro</td><td>junta; parelha; par</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zeugkteria-bdag\" data-source=\"BDAG\" data-search=\"ζευκτηρία, ας, ἡ substantivo feminino cabos de amarração; cordas dos lemes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζευκτηρία, ας, ἡ</td><td>substantivo feminino</td><td>cabos de amarração; cordas dos lemes</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zeus-bdag\" data-source=\"BDAG\" data-search=\"Ζεύς, Διός, acusativo Δία nome próprio masculino Zeus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ζεύς, Διός, acusativo Δία</td><td>nome próprio masculino</td><td>Zeus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zeo-bdag\" data-source=\"BDAG\" data-search=\"ζέω verbo ferver; entusiasmar-se; estar fervoroso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζέω</td><td>verbo</td><td>ferver; entusiasmar-se; estar fervoroso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zeleuo-bdag\" data-source=\"BDAG\" data-search=\"ζηλεύω verbo empenhar-se intensamente; ser zeloso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζηλεύω</td><td>verbo</td><td>empenhar-se intensamente; ser zeloso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zelos-bdag\" data-source=\"BDAG\" data-search=\"ζῆλος, ου, ὁ e ζῆλος, ους, τό substantivo masculino e neutro zelo; ardor; ciúme; inveja BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζῆλος, ου, ὁ e ζῆλος, ους, τό</td><td>substantivo masculino e neutro</td><td>zelo; ardor; ciúme; inveja</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zelotypia-bdag\" data-source=\"BDAG\" data-search=\"ζηλοτυπία, ας, ἡ substantivo feminino ciúme BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζηλοτυπία, ας, ἡ</td><td>substantivo feminino</td><td>ciúme</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zeloo-bdag\" data-source=\"BDAG\" data-search=\"ζηλόω verbo empenhar-se; desejar; cortejar; invejar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζηλόω</td><td>verbo</td><td>empenhar-se; desejar; cortejar; invejar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zelotes-bdag\" data-source=\"BDAG\" data-search=\"ζηλωτής, οῦ, ὁ substantivo masculino adepto zeloso; entusiasta; patriota; zelote BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζηλωτής, οῦ, ὁ</td><td>substantivo masculino</td><td>adepto zeloso; entusiasta; patriota; zelote</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article id=\"entry-zeta-numeral-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζ´</h1><div class=\"entry-meta\"><span>sinal numérico grego</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Sinal numérico que representa 7 (<span class=\"greek\">ἑπτά</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:10</a>, no códice D; GJs 10:1 (SyrBar 12:5); ou «sétimo» (<span class=\"greek\">ἑβδόμη</span>), Hm 7; [s 7], nas inscrições que servem de título ou sobrescrito (Apollon. Paradox. 33: <span class=\"greek\">Θεόφραστος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ζ</span>´ <span class=\"greek\">περὶ</span> <span class=\"greek\">φυτῶν</span>).</p></section></article>\n<article id=\"entry-zaboulon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζαβουλών, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Indeclinável (זְבוּלוּן); atestado na LXX, JosAs 27:6; Demetr.: 722 Fgm. 1, 5 Jac.; Fílon, Fuga 73; Test12Patr. Josefo, segundo seu uso habitual, provavelmente declinaria <span class=\"greek\">Ζαβουλών</span> (Ant. 1, 308; 2, 179), genitivo -<span class=\"greek\">ῶνος</span>. <strong>Zebulom</strong> (Gn 30:20), tribo israelita em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 7:8</a>; seu território, ao lado do de Naftali, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:13</a>, 15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:31</a>, códice D.</p></section></article>\n<article id=\"entry-zakchaios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζακχαῖος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(זַכַּי) Nesta forma também em W. Crum, <em>Coptic Ostraca</em> (1902), 435, 7, segundo a restauração de Wilcken: APF 2, 1903, p. 174, 3; 2Mc 10:19. Na forma <span class=\"greek\">Σακχαῖος</span>, Josefo, Vi. 239. Sobre <span class=\"greek\">Ζαχαῖος</span>, ver Preisigke, <em>Namenbuch</em>. <strong>Zaqueu</strong>, chefe dos publicanos de Jericó, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:2</a>, 5, 8. — M-M.</p></section></article>\n<article id=\"entry-zara-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζάρα, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(-<span class=\"greek\">ρά</span> nas edições; variante de leitura <span class=\"greek\">Ζάρε</span>; hebraico זֶרַח). <strong>Zerá</strong>, na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:3</a> (cf. 1Cr 2:4).</p></section></article>\n<article id=\"entry-zaphthani-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζαφθάνι</h1><div class=\"entry-meta\"><span>forma textual aramaica transliterada</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">É a leitura do códice D em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:46</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:34</a> em lugar de <span class=\"greek\">σαβαχθάνι</span>; trata-se de uma correção erudita baseada no hebraico (leia-se <span class=\"greek\">ἀζαφθάνι</span> = עֲזַבְתַּנִי; ver Dalman, <em>Worte</em>, 43; Wlh., <em>Mk</em>², 1909, ad 15:34; A. Merx, <em>D. vier kanon. Ev.</em> II/1, 1902, 424).</p></section></article>\n<article id=\"entry-zacharias-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζαχαρίας, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(זְכַרְיָה, «Zacarias»). Nome frequente no Antigo Testamento, em EpArist e Josefo (índice de Niese); Preisigke, <em>Namenbuch</em>.</p><p class=\"entry-text\">① Sacerdote, pai de João Batista, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:5</a>, 12s., 18, 21, 40, 59, 67; 3:2; GEb 13, 75; GJs (como sumo sacerdote; ver E. Amann, <em>Le Protévangile de Jacques et ses remaniements latines</em>, 1910, 213) 10:2; 23:1, 3; 24:1 (duas vezes), 2–4.</p><p class=\"entry-text\">② Zacarias de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:51</a>, identificado como filho de Baraquias (ver esse verbete) em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:35</a> (E. Nestle, ZNW 6, 1905, 198–200). Em GJs, idêntico ao da acepção ①.</p><p class=\"entry-text\">③ Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:9</a>, Zacarias (entendido como o profeta, sempre assim em Justino) constitui uma variante de leitura em lugar de Jeremias (sobre a confusão com Jeremias, cf., por exemplo, Orígenes, <em>In Matt.</em>, GCS 38, p. 249, 16ss.). — BHHW III, 2199.</p></section></article>\n<article id=\"entry-zao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">[ζάω]</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><strong>[<span class=\"greek\">ζάω</span>]</strong>, forma contraída <span class=\"greek\">ζῶ</span> (Homero e autores posteriores). Imperfeito <span class=\"greek\">ἔζων</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:9</a>, códice B: <span class=\"greek\">ἔζην</span>; sobre essa forma, Schwyzer I 675; B-D-F §88; Mlt-H. 194, ambos com referências). Futuro <span class=\"greek\">ζήσω</span> (atestação uniforme em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:9</a>); é mais frequente a forma posterior <span class=\"greek\">ζήσομαι</span> (desde Hipócrates VII, p. 536 L.; LXX; AscIs 3:9; Josefo, Ant. 1, 193 e outros; B-D-F §77; Rob. 356; sobre os futuros, J. Lee, NovT 22, 1980, 289–98; G. Kilpatrick, ibid. 25, 1983, 146–51). Primeiro aoristo <span class=\"greek\">ἔζησα</span>. Sobre o uso na LXX, Thackeray 269; sobre as formas nos papiros, Gignac II 370.</p><p class=\"entry-text\"><strong>① Estar fisicamente vivo, viver.</strong></p><p class=\"entry-text\">ⓐ Da vida física, em contraste com a morte.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <strong>Em geral:</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 22:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:1</a>, 2, 3; 14:8ac; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 5:15a</a>; 6:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:17</a>. <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">ζῶσα</span>, «alma vivente» (Gn 1:20 e outros; Justino, D. 6, 1, <span class=\"greek\">ζῇ</span> <span class=\"greek\">ψυχῇ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.45\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:45</a> (Gn 2:7); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16:3</a>, variante de leitura. <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἔτη</span> <span class=\"greek\">ζῇ</span>, «durante todos os anos em que vive», B 10:6 (cf. SIG 663, 6; Sb 173, 6, <span class=\"greek\">Αὐρήλιος</span> <span class=\"greek\">ζήσας</span> <span class=\"greek\">ἔτη</span> <span class=\"greek\">νε</span>´; En 10:10). <span class=\"greek\">τὸ</span> <span class=\"greek\">ζῆν</span>, «a vida» (escritores áticos, inscrições, papiros, LXX). <span class=\"greek\">ὥστε</span> <span class=\"greek\">ἐξαπορηθῆναι</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ζῆν</span>, «a ponto de desesperarmos até da própria vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:8</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ζῆν</span>, «durante a vida inteira», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:15</a> (cf. Diodoro Sículo 1, 74, 3, <span class=\"greek\">διατελεῖν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ζῆν</span> <span class=\"greek\">χρόνον</span>; 4, 46, 4). <span class=\"greek\">ἔτι</span> <span class=\"greek\">ζῶν</span>, «enquanto ainda vivia», isto é, antes de morrer, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.63\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:63</a> (CB I/2, 660, n.º 618, <span class=\"greek\">Ζώσιμος</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ζῶν</span> <span class=\"greek\">κατεσκεύασεν</span>; 3Km 12:6). <span class=\"greek\">ζῶντες</span> <span class=\"greek\">ἐβλήθησαν</span> … <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">λίμνην</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πυρός</span>, «foram lançados vivos no lago de fogo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 19:20</a>. <span class=\"greek\">ζῶσα</span> <span class=\"greek\">τέθνηκεν</span>, «embora viva, está morta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:6</a> (cf. Sextus 7). <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ζῶντες</span>, «nós, durante nossa vida terrena», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:11</a>; a mesma expressão significa «nós, que ainda estamos vivos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 4:15</a>, 17. O contraste aqui é <span class=\"greek\">νεκροί</span>, como em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:38a</a>. <span class=\"greek\">ζῶντες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νεκροί</span>, «vivos e mortos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:9b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 4:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4:5</a>; 2Cl 1:1; B 7:2. O contraste entre <span class=\"greek\">νεκρός</span> e <span class=\"greek\">ζῆν</span> às vezes se emprega figuradamente, com referência ao domínio religioso e ético, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:24</a>, variante de leitura; 15:32.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Sobre os mortos que retornam à vida, «reviver, voltar a viver»: pessoas em geral (3Km 17:23), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:41</a>; 20:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 20:4</a>, 5; AcPl Ha 11, 7. Sobre Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:5</a>, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:3</a>; 25:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:9a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 13:4a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:18b</a>; 2:8 (Justino, D. 69, 6, <span class=\"greek\">νεκροὺς</span> … <span class=\"greek\">ζῆν</span> <span class=\"greek\">ποιήσας</span>).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Sobre enfermos cuja doença termina não em morte, mas em recuperação: «estar bem, recuperar-se» (Artemidoro 4, 4, <span class=\"greek\">ἔζησεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">παῖς</span> = «o menino se recuperou»; 5, 71; 72; PGM 1, 188; 4Km 1:2; 8:8, <span class=\"greek\">εἰ</span> <span class=\"greek\">ζήσομαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀρρωστίας</span> <span class=\"greek\">μου</span> <span class=\"greek\">ταύτης</span>; Josefo, Vi. 421), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.50\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:50</a>, 51, 53. Também se aplica ao desaparecimento de ansiedade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 3:8</a>.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. Mesmo de pessoas sadias: «continuar a viver, permanecer vivo» (Xenofonte, An. 3, 2, 39, <span class=\"greek\">ὅστις</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ζῆν</span> <span class=\"greek\">ἐπιθυμεῖ</span> <span class=\"greek\">πειράσθω</span> <span class=\"greek\">νικᾶν</span>; carta 56 de Apolônio de Tiana [Filóstrato I 359, 14]; ApcMos 31, <span class=\"greek\">διὰ</span> <span class=\"greek\">τί</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">ἀποθνῄσκεις</span> <span class=\"greek\">καγὼ</span> <span class=\"greek\">ζῶ</span>;), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:24</a>; 28:4. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">θελήσῃ</span> <span class=\"greek\">ζήσομεν</span>, «se o Senhor quiser, viveremos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4:15</a>. <span class=\"greek\">ὸ</span>̓<span class=\"greek\">ς</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πληγὴν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μαχαίρης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔζησεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13:14</a>.</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. De seres que, na realidade ou na maneira como são representados, não estão sujeitos à morte: Melquisedeque, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:8</a> (em contraste com <span class=\"greek\">ἀποθνῄσκοντες</span> <span class=\"greek\">ἄνθρωποι</span>); Jesus, como sumo sacerdote eterno, <span class=\"greek\">πάντοτε</span> <span class=\"greek\">ζῶν</span>, «vivendo sempre», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:25</a>. Nesse sentido aplica-se sobretudo a Deus (ver C. Burchard, Untersuch. zu JosAs, p. 103): (<span class=\"greek\">ὁ</span>) <span class=\"greek\">θεὸς</span> (<span class=\"greek\">ὁ</span>) <span class=\"greek\">ζῶν</span>, «(o) Deus vivo» (cf. 4Km 19:4, 16; Is 37:4, 17; Os 2:1; Dn 6:21, Teodocião; 3Mc 6:28; TestAbr A 17, p. 99, 10 [Stone, p. 46]; TestJob 37:2; JosAs 49:3 e outros; SibOr 3, 763; POxy 924, 11 [século IV d.C., gnóstico]; PGM 4, 1038, <span class=\"greek\">ὁ</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">ζῶν</span> <span class=\"greek\">θεός</span>; 7, 823; 12, 79; Fílon, Decal. 67, <span class=\"greek\">ὁ</span> <span class=\"greek\">ζῶν</span> <span class=\"greek\">ἀεὶ</span> <span class=\"greek\">θεός</span>; Orígenes, C. Cels. 8, 59, 18. A expressão «o Deus vivo» não ocorre em Josefo): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:16</a>; 26:63; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.69\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:69</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9:26</a> (Os 2:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:3</a>; 6:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 3:15</a>; 4:10; 6:17, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:12</a>; 9:14; 10:31; 12:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:18a</a>; 4:10; 7:2; 10:6; 2Cl 20:2; GJs 20:1; AcPl Ha 2, 32. Também <span class=\"greek\">ὁ</span> <span class=\"greek\">ζῶν</span> <span class=\"greek\">πατήρ</span>, «o Pai vivo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.57\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:57</a>. Com o acréscimo <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">αἰῶνας</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">αἰώνων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 15:7</a>; cf. 4:9 (cf. Tb 13:2; Eclo 18:1). Deus faz juramento soberano com as palavras <span class=\"greek\">ζῶ</span> <span class=\"greek\">ἐγώ</span>, «tão certo como eu vivo» (Nm 14:28 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:11</a> (Is 49:18; paralelos clássicos em G. Stählin, NovT 5, 1962, 142, nota 2). <span class=\"greek\">ζῇ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> [<span class=\"greek\">μου</span>], «tão certo como vive o Senhor meu Deus», GJs 4:1; 6:1; 13:3; 15:3; 19:3 (Jz 8:19; 1Sm 25:34 e outros; GrBar 1:7; cf. ApcEsdr 2:7); forma ampliada <span class=\"greek\">καὶ</span> <span class=\"greek\">ζῇ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">αὐτοῦ</span>, 15:4 (ver de Strycker, ad loc.). Cristo vive <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πατέρα</span>, «por causa do Pai», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.57\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:57b</a> (ver Bultmann, comentário ao lugar).</p><p class=\"entry-text\">ⓑ Com menção daquilo de que a vida depende: <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, «com base em algo» (Andócides 1, 100; Isócrates 10, 18; Élio Aristides 28, 103 K. = 49, p. 525 D.). <span class=\"greek\">ζ</span>. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἄρτῳ</span>, «viver de pão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:4</a> (ambos Dt 8:3). <span class=\"greek\">ζ</span>. <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, «tirar de algo o próprio sustento» (Aristófanes, Eccl. 591; Demóstenes 57, 36; POxy 1117, 19; 1557, 12; TestJob 47:1s.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9:14</a>.</p><p class=\"entry-text\">ⓒ Com especificação mais precisa da esfera da vida (Artemidoro 3, 62, <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγορᾷ</span> <span class=\"greek\">ζ</span>. = «passar a vida na praça do mercado»). <span class=\"greek\">ζ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span>, «viver na carne», em contraste com a vida celeste, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:20c</a>. <span class=\"greek\">ζ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">κόσμῳ</span>, «viver no mundo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2:20</a>. <span class=\"greek\">ζ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">θεῷ</span>, «viver em Deus» (como o Ser que penetra e abrange todas as coisas), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:28</a> (ver <span class=\"greek\">κινέω</span> 3). Sobre AcPl Ha 1, 15, ver 2a, ao final.</p><p class=\"entry-text\"><strong>② Viver em sentido transcendente</strong>, referindo-se à vida santificada de um filho de Deus (<span class=\"greek\">ζῆν</span> denota um tipo de vida superior à vida animal: Xenofonte, Mem. 3, 3, 11; Cássio Díon 69, 19; depois de anos de serviço público, Similis retira-se e prepara seu epitáfio: <span class=\"greek\">Σίμιλις</span> <span class=\"greek\">ἐνταύθα</span> <span class=\"greek\">κεῖται</span> <span class=\"greek\">βιοὺς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἔτη</span> <span class=\"greek\">τόσα</span>, <span class=\"greek\">ζήσας</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἔτη</span> <span class=\"greek\">ἑπτά</span>, «Aqui jaz Similis, que existiu tantos anos, mas viveu apenas sete»).</p><p class=\"entry-text\">ⓐ No mundo: <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ἔζων</span> <span class=\"greek\">χωρὶς</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">ποτέ</span>, «em outro tempo, eu vivia [verdadeiramente] sem lei». Isso tem sido interpretado como referência a um tempo em que a lei não existia, de modo que Paulo falaria do ponto de vista da humanidade no paraíso antes do mandamento (Gn 2:16s.; 3:3). Outra interpretação entende que Paulo alude ao período em que não tinha consciência da existência e importância da lei. Em vista de sua declaração culminante em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:25</a>, Paulo provavelmente exemplifica, na primeira pessoa, os perigos de um cristão que sucumbe à ilusão de que a conduta moral se liga à lei, e não ao «Espírito de vida em Cristo» (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:2</a>): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:9</a>. Já agora os que escutam a voz do Filho de Deus desfrutam dessa vida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:25</a>; cf. 11:26; igualmente aqueles que o recebem em seu ser, <span class=\"greek\">ὁ</span> <span class=\"greek\">τρώγων</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄρτον</span>, 6:57c; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6:11</a>, 13 (<span class=\"greek\">ἐκ</span> <span class=\"greek\">νεκρῶν</span> <span class=\"greek\">ζῶντας</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:1</a>. Essa vida celeste na terra é <span class=\"greek\">ζ</span>. <span class=\"greek\">πνεύματι</span>, «viver pelo Espírito», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:25</a>, ou uma vida que não resulta de mera realização humana, mas de Cristo vivendo nos cristãos, Gl 2:20ab. Também sobre o poder sobre-humano do apóstolo: <span class=\"greek\">ζήσομεν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">δυνάμεως</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑμᾶς</span>, «viveremos com ele [Cristo], mediante o poder de Deus, em nossas relações convosco», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 13:4</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">βούλεται</span> <span class=\"greek\">ζῆν</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θεῷ</span>, «o Senhor quer que vivamos sob a direção de Deus», AcPl Ha 1, 15 (em contraste com <span class=\"greek\">ἀποθανεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἁμαρτίαις</span>; ver 1c, ao final).</p><p class=\"entry-text\">ⓑ Na glória da vida futura (Eclo 48:11; cf. Dt 4:1; 8:1; 30:16).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Em emprego absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:25</a>; 14:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:13b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:9</a>. <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ζῆν</span> <span class=\"greek\">Χριστός</span>, «para mim, a vida só é possível onde Cristo está» (de modo que a morte é lucro), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:21</a> (ver O. Schmitz, <em>G. Heinrici Festschrift</em>, 1914, 155–69). Outra interpretação comum: «para mim, viver é Cristo», isto é, enquanto vive, Paulo experimenta a vida real em união com Cristo; com a morte, chega a vida em toda a plenitude na presença de Jesus.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Mais especificamente <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span>, «ter vida eterna» (Pseudo-Luciano, Philopatr. 17, <span class=\"greek\">ζῆν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span>; PsSol 14:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.51\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:51</a>, 58 (em João, a vida bem-aventurada que o seguidor de Jesus desfruta aqui e agora no corpo simplesmente continua na vida celeste futura; também em outros aspectos, a linha divisória entre a vida presente e a futura por vezes não existe ou, ao menos, não é perceptível); B 6:3; 8:5; 9:2; 11:10s. <span class=\"greek\">ἅμα</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span> (isto é, <span class=\"greek\">Χριστῷ</span>) <span class=\"greek\">ζ</span>., «viver juntamente com Cristo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:10</a>; <span class=\"greek\">ζ</span>. <span class=\"greek\">δι</span>’ <span class=\"greek\">αὐτοῦ</span>, «viver por meio dele» (isto é, Cristo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 4:9</a>; <span class=\"greek\">ζ</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">πνεύματι</span>, «viver no Espírito como Deus [vive]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4:6</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">δίκαιος</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">ζήσεται</span> (cf. Hc 2:4), «aquele que é justo pela fé terá vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:17</a> (A. Feuillet, NTS 6, 1959, 52–80; mas ver Fitzmyer, <em>Romans</em> [AB], ad loc.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:38</a>. Essa vida é <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀληθινὸν</span> <span class=\"greek\">ζῆν</span>, «a verdadeira vida», ITr 9:2; IEph 11:1. Cristo é chamado <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀδιάκριτον</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ζῆν</span>, «nossa vida inabalável ou inseparável», IEph 3:2; <span class=\"greek\">τὸ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ζῆν</span>, «nossa vida integral», IMg 1:2. A pessoa orientada pela lei crê, a respeito de sua observância: <span class=\"greek\">ὁ</span> <span class=\"greek\">ποιήσας</span> <span class=\"greek\">αὐτὰ</span> <span class=\"greek\">ζήσεται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτοῖς</span>, «aquele que praticar essas coisas viverá por elas» (Lv 18:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:12</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10:5</a> (cf. Díon Crisóstomo 58 [75], 1, <span class=\"greek\">οἱ</span> <span class=\"greek\">τοῦτον</span> [= <span class=\"greek\">τ</span>. <span class=\"greek\">νόμον</span>] <span class=\"greek\">φυλάττοντες</span> <span class=\"greek\">ἔχονται</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σωτηρίας</span>, «os que observam a lei estão firmemente seguros»).</p><p class=\"entry-text\"><strong>③ Conduzir-se segundo determinado padrão de comportamento, viver</strong> (Homero e outros).</p><p class=\"entry-text\">ⓐ Com advérbios ou outros modificadores: advérbios (Sallust. 19, p. 34, 25, <span class=\"greek\">κακῶς</span> <span class=\"greek\">ζῆν</span> [Justino, A I, 4, 7]; SIG 889, 13ss.; Sb 14:28; Fílon; Josefo, Ant. 12, 198; Ath. 3, 1, <span class=\"greek\">δίκην</span> <span class=\"greek\">θηρίων</span>); <span class=\"greek\">ἀσώτως</span>, «dissolutamente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:13</a>; <span class=\"greek\">ἐθνικῶς</span> e <span class=\"greek\">ἰουδαϊκῶς</span>, «segundo o modo dos gentios» e «dos judeus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:14</a>; <span class=\"greek\">εὐσεβῶς</span>, «piedosamente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3:12</a>; <span class=\"greek\">πανούργως</span>, «astutamente», Hm 3, 3. <span class=\"greek\">σωφρόνως</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δικαίως</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εὐσεβῶς</span>, «com sobriedade, justiça e piedade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:12</a> (Plutarco, Mor. 1108c, <span class=\"greek\">ζῆν</span> <span class=\"greek\">σωφρόνως</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δικαίως</span>; cf. Diógenes Laércio 10, 132; 140; Ar. 15, 10). <span class=\"greek\">Φαρισαῖος</span>, «viver como fariseu», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:5</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πίστει</span>, «na fé», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:20d</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἁμαρτίᾳ</span>, «no pecado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6:2</a>; <span class=\"greek\">ζ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτοις</span>, «viver nesses [pecados]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3:7</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἀλήθειαν</span>, «segundo a verdade», IEph 6:2 (cf. Fílon, Post. Cai. 73, <span class=\"greek\">κατὰ</span> <span class=\"greek\">βούλημα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ζ</span>.; Josefo, Ant. 4, 302, <span class=\"greek\">κατὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">νόμους</span> <span class=\"greek\">ζ</span>.; Justino, D. 47, 4, <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span>; Orígenes, C. Cels. 7, 12, 7, <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">θείας</span> <span class=\"greek\">γραφάς</span>). <span class=\"greek\">κατὰ</span> <span class=\"greek\">θεόν</span>, «segundo Deus», IEph 8:1 (cf. SIG 910 A e B). <span class=\"greek\">κατὰ</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">Χριστόν</span>, «segundo Jesus Cristo», IPhld 3:2. <span class=\"greek\">κατὰ</span> <span class=\"greek\">Χριστιανισμόν</span>, «viver conforme [nosso] compromisso com Cristo», IMg 10:1. <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span>, «segundo a carne», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:12s</a>.; Dg 5:8. <span class=\"greek\">κατὰ</span> <span class=\"greek\">κυριακὴν</span> <span class=\"greek\">ζ</span>. (em contraste com <span class=\"greek\">σαββατίζειν</span>), «incluir a observância do dia do Senhor na própria vida», IMg 9:1. Sobre uma mulher casada, <span class=\"greek\">ζ</span>. <span class=\"greek\">μετὰ</span> <span class=\"greek\">ἀνδρός</span>, «viver com o marido», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:36</a> (sobre o acusativo adicional de duração, cf. Élio Aristides 46, p. 332 D.; Pv 28:16; <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἔζησεν</span> <span class=\"greek\">καλῶς</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">ἔτη</span> 28, <span class=\"greek\">μῆνας</span> 4, <span class=\"greek\">ἡμέρας</span> 5, SEG II, 384, 6–8 [restaurado]; ver também F. Danker, <em>Jesus and the New Age</em>, 1988, 71).</p><p class=\"entry-text\">ⓑ Com dativo <span class=\"greek\">τινί</span>, «viver por alguém ou alguma coisa», em benefício do outro (Homero e outros; Demóstenes 7, 17, <span class=\"greek\">οἳ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">αἰσχύνονται</span> <span class=\"greek\">Φιλίππῳ</span> <span class=\"greek\">ζῶντες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">πατρίδι</span>; Dionísio de Halicarnasso 3, 17, … <span class=\"greek\">παῖδες</span>, <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρὶ</span> <span class=\"greek\">ζῶντες</span>). <span class=\"greek\">ζ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, «viver para Deus» (4Mc 7:19; 16:25; Fílon, Mut. Nom. 13, Rer. Div. Her. 111; ver S. Aalen, NTS 13, 1967, 10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:38b</a> (cf. Sófocles, Ajax 970); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6:10</a>, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:19</a>; Hm 3:5; AcPl Ha 10, 7. <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span>, «para o Senhor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:8b</a> (cf. Plutarco, Cleom. 819 [31, 5]). Para Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 5:15</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐμῷ</span> <span class=\"greek\">βασιλεῖ</span>, «para meu rei», AcPl Ha 9, 26 (restaurado segundo Aa I 112, 14). <span class=\"greek\">τῇ</span> <span class=\"greek\">δικαιοσύνῃ</span> <span class=\"greek\">ζ</span>., «viver para a justiça», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:24</a>. <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">ζ</span>., «viver para si mesmo» (Menandro, Fgm. 646 Kö., <span class=\"greek\">οὐχ</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">ζῆν</span> <span class=\"greek\">μόνον</span>; Diodoro Sículo 10, 33, 2, <span class=\"greek\">ζ</span>. <span class=\"greek\">ἑαυτοῖς</span> = «viver para si mesmos»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:7</a>.</p><p class=\"entry-text\"><strong>④ Estar cheio de vitalidade, ser vivaz</strong>: o particípio é usado figuradamente a respeito de coisas (cf. <span class=\"greek\">τῶν</span> <span class=\"greek\">δένδρων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ζῶντων</span>, ParJer 9:3); sobre água de nascente em contraste com água de cisterna, <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">ζῶν</span>, «água viva» (Gn 26:19; Lv 14:5; Jr 2:13, variante de leitura; Zc 14:8; água parada é chamada <span class=\"greek\">ὕ</span>. <span class=\"greek\">νεκρόν</span>: Sinésio, Ep. 114, 254d), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:10s</a>. (Hdb., comentário sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:14</a>); 7:38; D 7:1s. (Wengst, p. 77, nota 57). <span class=\"greek\">ζώσας</span> <span class=\"greek\">πηγάς</span>, «fontes vivas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 7:17</a>, variante de leitura.</p><p class=\"entry-text\"><strong>⑤ Ser produtor de vida, oferecer vida</strong>: o particípio é usado a respeito de coisas (SIG 1173 [138 d.C.], 5, <span class=\"greek\">ζῶσαι</span> <span class=\"greek\">ἀρεταὶ</span> <span class=\"greek\">ἐγένοντο</span> = «ocorreram milagres cheios de vida divina»). <span class=\"greek\">λόγια</span> <span class=\"greek\">ζῶντα</span>, «palavras que significavam vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:38</a>; <span class=\"greek\">λόγος</span> <span class=\"greek\">ζῶν</span> <span class=\"greek\">θεοῦ</span>, «palavra viva de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:23</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:12</a>. <span class=\"greek\">ὁδὸς</span> <span class=\"greek\">ζῶσα</span>, «caminho vivo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:20</a>; <span class=\"greek\">ἐλπὶς</span> <span class=\"greek\">ζῶσα</span>, «esperança viva», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:3</a>. Também descreve pessoas que comunicam a vida divina: Cristo, <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄρτος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ζῶν</span>, «o pão vivo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.51\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:51a</a>; <span class=\"greek\">λίθος</span> <span class=\"greek\">ζῶν</span>, «pedra viva», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:4</a>. Cristãos: <span class=\"greek\">θυσία</span> <span class=\"greek\">ζῶσα</span>, «sacrifício vivo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12:1</a>; <span class=\"greek\">λίθοι</span> <span class=\"greek\">ζῶντες</span>, «pedras vivas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:5</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">ζώσης</span> <span class=\"greek\">φωνῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μενούσης</span>, «as [palavras] de uma voz viva e permanente», Pápias (2:4), em contraste com <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">βιβλίων</span> («dos livros»). Sobre a bibliografia, ver o fim de <span class=\"greek\">ζωή</span>. DELG, s.v. <span class=\"greek\">ζώω</span>; M-M; TW.</p><p class=\"entry-text\">Nota de abreviação: <span class=\"greek\">ζ</span>. representa o verbo do presente artigo.</p></section></article>\n<article id=\"entry-zbennymi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζβέννυμι</h1><div class=\"entry-meta\"><span>verbo remissivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(PGM 7, 364, no manuscrito; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:19</a>, variante de leitura) — Ver <span class=\"greek\">σβέννυμι</span>. — M-M.</p></section></article>\n<article id=\"entry-zebedaios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζεβεδαῖος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(זַבְדַּי; Josefo, Ant. 5, 33; PGrenf II, 113, 42; Justino, D. 106, 3). <strong>Zebedeu</strong>, pai dos apóstolos João e Tiago, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:21</a>; 10:2; 20:20; 26:37; 27:56; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:19s</a>.; 3:17; 10:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21:2</a>. — BHHW III, 2205.</p></section></article>\n<article id=\"entry-zestos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεστός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Com o sentido de «fervido, cozido» em Apiano; referindo-se à água «fervente» em Nicandro, Fgm. 70, 11s., <span class=\"greek\">ζεστὸν</span> <span class=\"greek\">ὕδωρ</span>; Estrabão; Sorano, p. 37, 2 e outros; Dioscórides; Sexto Empírico; SibOr 3, 461). <strong>Quente</strong>. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:15s</a>., a ideia subjacente é que os membros da comunidade de Laodiceia são espiritualmente tão ineficazes quanto sua água é, em grande parte, desagradável ao paladar, sendo imprópria para beber (quanto à aplicação a pessoas, cf. Etym. Mag. 413, 23, <span class=\"greek\">ζεστὸν</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">φαμὲν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">εὐκίνητον</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θερμόν</span>). M. Rudwick e E. Green, ET 69, 1957/58, 176–78; C. Hemer, <em>The Letters to the Seven Churches of Asia in Their Local Setting</em>, 1989 [1986], 186–91. Ver <span class=\"greek\">χλίαρος</span> e <span class=\"greek\">ψυχρός</span>. — DELG, s.v. <span class=\"greek\">ζέω</span>; TW.</p></section></article>\n<article id=\"entry-zeugnymi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεύγνυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e outros; inscrições; LXX; JosAs; ApcrEzk [Epifânio 70, 15]; Justino, D. 132, 2; Taciano 15, 1). Aoristo <span class=\"greek\">ἔζευξα</span>, LXX. Passiva: aoristo, terceira pessoa do plural <span class=\"greek\">ἐζεύχθησαν</span>, 1Mc 1:15, variante de leitura; particípio perfeito <span class=\"greek\">ἐζευγμένος</span>, 2Km 20:8 (JosAs 5:5). <strong>Ligar, unir (sob um jugo)</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:9</a>, variante de leitura em lugar de <span class=\"greek\">συνέζευξεν</span> (sobre união matrimonial, também Partênio 17, 3; Apiano, Basil. 1 §1, Bell. Civ. 2, 14 §50; Ateneu 12, 554b; Sb 6647, 5; Josefo, Ant. 16, 11). — B. 843; DELG.</p></section></article>\n<article id=\"entry-zeugos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζεῦγος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">① <strong>Junta de dois animais de tração unidos por uma armação comum; jugo, parelha</strong>, <span class=\"greek\">ζεῦγος</span> <span class=\"greek\">βοῶν</span> (Homero e outros; Diodoro Sículo 14, 18, 5; Arriano, Anab. 2, 3, 2; PPetr III, 31, 5 [240 a.C.]; 3Km 19:21; Jó 1:3, 14; 42:12; TestAbr A 2, p. 78, 14 [Stone, p. 4]; TestJob 10:5 e outros; cf. Josefo, Ant. 8, 353; 12, 192), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:19</a>. A menos que o autor pretenda destacar que os dez bois (<span class=\"greek\">ζεύγη</span> <span class=\"greek\">πέντε</span>) eram vendidos como animais de trabalho bem treinados, o termo também pode ter o sentido mais geral da acepção ② (em ambos os sentidos, trata-se de empréstimo no vocabulário rabínico).</p><p class=\"entry-text\">② <strong>Par</strong> (Ésquilo, Ag. 44; Heródoto 3, 130; Xenofonte, Oec. 7, 18; OGI 533, 6; 47; POxy 267, 6 [36 d.C.], <span class=\"greek\">ἐνωτίων</span> <span class=\"greek\">ζ</span>.; BGU 22, 31 [114 d.C.], <span class=\"greek\">ζ</span>. <span class=\"greek\">ψελλίων</span>). <span class=\"greek\">ζ</span>. <span class=\"greek\">τρυγόνων</span>, «um par de rolas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:24</a> (Lv 5:11; sobre pombas, também Sb 7814, 21; 24 [256 d.C.]). — DELG, s.v. <span class=\"greek\">ζεύγνυμι</span> II; Frisk, s.v. <span class=\"greek\">ζεῦγος</span>; M-M; TW.</p></section></article>\n<article id=\"entry-zeugkteria-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζευκτηρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">ζεύγνυμι</span>.) <strong>Algo usado para ligar coisas</strong> (habitualmente duas) entre si; <strong>faixas, cabos que prendiam os lemes</strong>; o termo técnico náutico é <em>pendant</em> ou <em>pennant</em> (OED, s.v. «pennant»; L. Casson, <em>Ships, etc. in the Ancient World</em>, 1971, 228), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.40\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:40</a>. O adjetivo <span class=\"greek\">ζευκτήριος</span> é atestado desde Ésquilo, Pers. 736. O substantivo neutro significa «jugo» no singular em Ésquilo, Ag. 515; PHerm 95, 18; no plural, <span class=\"greek\">τὰ</span> <span class=\"greek\">ζευκτήρια</span>; PLond III, 1177, 167 [113 d.C.], p. 185, <span class=\"greek\">σχοινίων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ζευκτηρίων</span>; POxy 934, 5; PFlor 16, 26 e outros papiros. Sobre o procedimento, cf. Eurípides, Hel. 1552, <span class=\"greek\">πηδάλια</span> <span class=\"greek\">ζεύγλαισι</span> <span class=\"greek\">παρακαθίετο</span>; Breusing 102–3. — DELG, s.v. <span class=\"greek\">ζεύγνυμι</span> I.</p></section></article>\n<article id=\"entry-zeus-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζεύς, Διός, acusativo Δία</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e outros; inscrições; 2Mc 6:2; EpArist 16; Fílon; Josefo; SibOr; escritos apologéticos, exceto Mel.). <strong>Zeus</strong>, rei dos deuses gregos, que a população de Listra imaginou ter aparecido na pessoa de Barnabé, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:12</a>. Seu papel de benfeitor dos dedicados às atividades agrícolas (cf. o Hino a Zeus Dicteu em AnthLG, Diehl² II, 279–81) provavelmente constitui parte da motivação que explica a descrição contrastante do «Deus vivo» (versículos 15–17) e a reação extraordinária dos ouvintes (versículo 18). <span class=\"greek\">ὁ</span> <span class=\"greek\">ἱερεὺς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Διὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὄντος</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόλεως</span>, «o sacerdote de [templo ou santuário de] Zeus localizado diante da cidade», versículo 13 (cf. Cáriton 4, 4, 9, <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἀφροδίτην</span> <span class=\"greek\">βαδίζειν</span>; Filóstrato I 363, 17, <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἀρτέμιδι</span> = «no templo de Ártemis»; C. Breytenbach, NTS 39, 1993, 396–413 [inscrições]). — Bibliografia: LfgrE 860, s.v. <span class=\"greek\">Ζεύς</span>; também SEG XLIII, 1311; 1758–71. Ver o verbete <span class=\"greek\">Λύστρα</span>.</p></section></article>\n<article id=\"entry-zeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Particípio <span class=\"greek\">ζέων</span>. Literalmente, «ferver, estar em ebulição» (Homero e outros; GDI, p. 1034, n.º 3 [Creta, século II a.C.], regulamento religioso <span class=\"greek\">καταχέαι</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">ζέον</span>; papiros; Jó 32:19; Josefo, Bell. 3, 271; Ant. 13, 345; Ath.). Figuradamente, de emoções, ira, amor e desejo intenso de fazer bem ou mal: <strong>estar emocionalmente agitado, estar entusiasmado, excitado, ardendo de fervor</strong> (trágicos; Platão, Rep. 440c; Cáriton 1, 5, 1; Plutarco, Mor. 1088f; 4Mc 18:20; Fílon, Mos. 2, 280). <span class=\"greek\">ζέων</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span>, sobre Apolo antes de tornar-se membro plenamente integrado à comunidade cristã, «ardendo de zelo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 18:25</a> (cf. Eunápio, p. 82, <span class=\"greek\">ζέοντος</span> <span class=\"greek\">δαίμονος</span>, isto é, do orador; ver ainda H. Preisker, ZNW 30, 1931, 301–4; R. Strelan, <em>Paul, Artemis, and the Jews in Ephesus</em>, BZNW 80, 1996, 216–29). A exortação aos cristãos para serem <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">ζέοντες</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12:11</a>, manda-os conservar o ardor espiritual (Moffatt). — B. 676; Straub 20; DELG; M-M; TW.</p></section></article>\n<article id=\"entry-zeleuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Cf. <span class=\"greek\">ζηλόω</span> e o verbete seguinte; Demócrito, Fgm. B 55, variante de leitura; Simplício, comentário sobre Epicteto, p. 56d; Leôncio 44a, p. 89, 2; <em>Cat. Cod. Astr.</em> X 219, 8). Em emprego absoluto: <strong>levar algo muito a sério, empenhar-se, mostrar zelo ou dedicação</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:19</a>. — DELG, s.v. <span class=\"greek\">ζῆλος</span>.</p></section></article>\n<article id=\"entry-zelos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζῆλος, ου, ὁ e ζῆλος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo masculino e neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">No Novo Testamento, masculino singular, exceto em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9:2</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:6</a> (ambos com variante de leitura masculina); genitivo neutro apenas em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:17</a>, variante de leitura; plural masculino apenas em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:20</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:20</a>, variantes de leitura. Nos Padres Apostólicos, mais frequentemente masculino, mas neutro singular em ITr 4:2 e 1Cl 4:8; 9:1; 11:13; 14:1; 63:2. Sobre o uso na LXX, Thackeray 158, 5; cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">ζήλει</span>, PsSol 2:24; 4:3; <span class=\"greek\">τὸ</span> <span class=\"greek\">ζῆλος</span>, TestGad 5:3 (variante <span class=\"greek\">μῖσος</span>); em Test12Patr, <span class=\"greek\">ὁ</span> <span class=\"greek\">ζῆλος</span>, mas com neutro em variantes. Plural <span class=\"greek\">ζήλη</span> (GrBar 8:5). Ver o verbete anterior e <span class=\"greek\">ζηλόω</span>.</p><p class=\"entry-text\">① <strong>Interesse positivo e intenso por algo, zelo, ardor</strong>, caracterizado por dedicação (desde Sófocles, Aj. 503; Aristóteles, Rhet. 2, 11, 1; LXX; TestAsh 4:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9:2</a>. Com <span class=\"greek\">σπουδή</span> (Díon Crisóstomo 17 [34], 48), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 7:11</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">ζ</span>., «quanto ao zelo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:6</a>. Com genitivo objetivo (Sófocles, Oed. Col. 943; Estrabão 13, 2, 4; Plutarco, Cor. 215 [4, 3]; Luciano, Adv. Ind. 17; 1Mc 2:58; frequentemente Fílon; Josefo, C. Ap. 2, 271): <span class=\"greek\">ζ</span>. <span class=\"greek\">θεοῦ</span>, «zelo por Deus» (Jt 9:4; cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">ζήλῳ</span> <span class=\"greek\">κυρίου</span>, TestAsh 4:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10:2</a>. <span class=\"greek\">ζ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">οἴκου</span> <span class=\"greek\">σου</span>, «zelo por tua casa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2:17</a> (Sl 68:10). Nesse sentido também com <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span>: <span class=\"greek\">τὸν</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἐμοῦ</span>, «vosso ardor em meu favor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 7:7</a>; <span class=\"greek\">ἔχει</span> … <span class=\"greek\">ζῆλον</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ὑμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 4:13</a>, variante de leitura. Com genitivo de qualidade: <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ζῆλος</span>, «ardor semelhante ao de Deus» ou «ardor divino», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:2</a> (cf. Is 9:6; Fílon, Post. Cai. 183; sobre a concepção, F. Küchler, ZAW 28, 1908, 42ss.; B. Renaud, <em>Je suis un Dieu jaloux</em>, 1963). Sobre o fogo do juízo que, com suas chamas intensas, parece um ser vivo decidido a devorar os adversários de Deus: <span class=\"greek\">πυρὸς</span> <span class=\"greek\">ζῆλος</span> <span class=\"greek\">ἐσθίειν</span> <span class=\"greek\">μέλλοντος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὑπεναντίους</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:27</a> (cf. Is 26:11; Sf 1:18; 3:8; Sl 78:5).</p><p class=\"entry-text\">② <strong>Sentimentos negativos e intensos diante das realizações ou do êxito alheio; ciúme, inveja</strong> (Hesíodo, Op. 195; Lísias 2, 48, com <span class=\"greek\">φθόνος</span>; Plutarco, Thes. 6, 9; Lycurg. 41 [4, 3]; PGrenf I, 1, 13 [século II a.C.]; Ec 4:4; 9:6; Eclo 30:24; 40:4 [ambos com <span class=\"greek\">θυμός</span>]; Test12Patr [exceto TestAsh 4:5]; AscIs 3:30; Josefo, Ant. 14, 161; cf. Cícero, Tusc. Disp. 4, 8, 17), 1Cl 3:2; 4:7ss.; 5:2, 4s.; 6:1ss.; 43:2; 63:2. Com <span class=\"greek\">ἔρις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13:13</a>; 1Cl 5:5; 6:4; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:20</a> (nessas três últimas passagens, <span class=\"greek\">ζῆλος</span> parece coordenado com <span class=\"greek\">ἔρις</span> no sentido de «rivalidade» ou «partidarismo»; cf. GrBar 8:5; 13:4). Com <span class=\"greek\">ἐριθεία</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:14</a>, 16; com <span class=\"greek\">φθόνος</span> (Demócrito, Fgm. B 191; Lísias 2, 48; Platão, Phlb. 47e, 50c; 1Mc 8:16), 1Cl 3:2; 4:7 e outros. <span class=\"greek\">πλησθῆναι</span> <span class=\"greek\">ζήλου</span>, «encher-se de inveja», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:17</a>; 13:45. O <span class=\"greek\">ζ</span>. conduz à morte, 1Cl 9:1; 39:7 (Jó 5:2). <span class=\"greek\">ζ</span>. <span class=\"greek\">ἄδικον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀσεβῆ</span>, 1Cl 3:4; <span class=\"greek\">μυσερὸν</span> <span class=\"greek\">ζ</span>., 14:1; <span class=\"greek\">μιαρὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἄδικον</span> <span class=\"greek\">ζ</span>., 45:4. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ζῆλόν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀλλήλοις</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, «ter ciúmes uns dos outros por causa de alguma coisa», Hs 8, 7, 4. O plural <span class=\"greek\">ζῆλοι</span>, encontrado como variante de leitura em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13:13</a> (ver início do verbete), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:20</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:20</a>, indica as diversas manifestações de ciúme e suas formas (cf. Platão, Leg. 3, 679c, <span class=\"greek\">ζῆλοί</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φθόνοι</span>); <span class=\"greek\">ζήλη</span> em lista de vícios, GrBar 8:5. — B. Reicke, <em>Diakonie, Festfreude u. Zelos …</em>, 1951, 231–393; DELG; M-M; EDNT; TW; Sv.</p></section></article>\n<article id=\"entry-zelotypia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλοτυπία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ésquines e outros; Políbio 4, 87, 4; Plutarco; Díon Crisóstomo 14 [31], 99 e outros; Luciano; Nm 5:15, 18, 25, 29; Fílon; Josefo, Ant. 7, 386; C. Ap. 2, 123). <strong>Ciúme</strong>, D 5:1. — B. 1139; DELG, s.v. <span class=\"greek\">ζῆλος</span>.</p></section></article>\n<article id=\"entry-zeloo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">ζῆλος</span>.) Futuro <span class=\"greek\">ζηλώσω</span>, Ez 39:25 (TestReub 6:5, <span class=\"greek\">ζηλώσετε</span> [variante -<span class=\"greek\">σατε</span>]); primeiro aoristo <span class=\"greek\">ἐζήλωσα</span>; perfeito <span class=\"greek\">ἐζήλωκα</span>, LXX (variante -<span class=\"greek\">σα</span>). Cf. <span class=\"greek\">ζῆλος</span>; Hinos Homéricos, Hesíodo e outros; inscrições, papiros; Tucídides 2, 64, 4, «emular, rivalizar»; Taciano 25, 1, <span class=\"greek\">ζηλῶν</span> … <span class=\"greek\">τὸν</span> <span class=\"greek\">κύνα</span>, «emulando o cão [o cínico]».</p><p class=\"entry-text\">① <strong>Ter interesse intenso e positivo por algo, esforçar-se, desejar, empenhar-se seriamente, dedicar-se</strong>.</p><p class=\"entry-text\">ⓐ Com coisa como objeto, acusativo <span class=\"greek\">τὶ</span>, «[esforçar-se] por algo» (Eurípides, Hec. 255; Tucídides 2, 37; Demóstenes 20, 141; Políbio 6, 25, 11, <span class=\"greek\">τὸ</span> <span class=\"greek\">βέλτιον</span>; Diodoro Sículo 1, 95, 4; PSI 94, 9, <span class=\"greek\">ζηλοῖ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μάθησιν</span>; Sb 1:12; Eclo 51:18, <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαθόν</span>; Josefo, C. Ap. 2, 261). <span class=\"greek\">ζ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">χαρίσματα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μείζονα</span>, «empenhar-se por obter os dons espirituais de maior valor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12:31</a> (J. Smit, NTS 39, 1993, 246–64 [interpretação irônica]). <span class=\"greek\">τὸ</span> <span class=\"greek\">προφητεύειν</span>, «profetizar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.39\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:39</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">πνευματικά</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:1</a> (além do acusativo, depende de <span class=\"greek\">ζ</span>. uma oração com <span class=\"greek\">ἵνα</span>).</p><p class=\"entry-text\">ⓑ Com pessoa como objeto, acusativo <span class=\"greek\">τινά</span>: <strong>ter profundo interesse por alguém, cortejar o favor de alguém, dar-lhe grande atenção</strong>, implicando o desejo de tê-lo a seu lado (<span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 13, 2, <span class=\"greek\">οἱ</span> <span class=\"greek\">ζηλοῦντες</span> <span class=\"greek\">ἐκείνους</span>; Pv 23:17; 24:1; passiva em Josefo, C. Ap. 1, 225), Gl 4:17ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:2</a>. <span class=\"greek\">μηδέν</span> <span class=\"greek\">με</span> <span class=\"greek\">ζηλώσαι</span>, «que nada me atraia [afastando-me do meu propósito]», IRo 5:3. Em emprego absoluto, «manifestar zelo» (Tucídides 2, 64, 4): <span class=\"greek\">ζήλωσον</span>, «toma posição, decide-te», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:19</a>, variante de leitura. Laodiceia é indecisa e recebe a exortação a demonstrar que a congregação é zelosa pelos interesses do Senhor. Na passiva, <span class=\"greek\">καλὸν</span> <span class=\"greek\">ζηλοῦσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">καλῷ</span> <span class=\"greek\">πάντοτε</span>, «é bom ser sempre objeto de atenção zelosa naquilo que é bom», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:18</a>.</p><p class=\"entry-text\">② <strong>Ter sentimentos negativos intensos diante das realizações ou do êxito de outra pessoa; encher-se de ciúme, invejar</strong>. Com acusativo <span class=\"greek\">τινά</span>, «em relação a alguém» (Hesíodo, Op. 23; Hinos Homéricos, Cer. 168, 223; Gn 26:14; 30:1; Demetr.: 722 Fgm. 1, 3 Jac.). <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰωσήφ</span>, «José», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:9</a> (cf. Gn 37:11). Em emprego absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 13:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4:2</a>; 2Cl 4:3; AcPl Ha 2, 11; 6, 31. — M-M; TW.</p></section></article>\n<article id=\"entry-zelotes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζηλωτής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Isócrates, Platão e outros; inscrições, LXX; JosAs 11, códice A [p. 53, 25 Bat.]; ApcSed 6:8; Fílon; Josefo; Ar.).</p><p class=\"entry-text\">① <strong>Aquele que se dedica ardorosamente a uma posição ou causa; entusiasta, adepto, partidário, lealista</strong>.</p><p class=\"entry-text\">ⓐ Com genitivo.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. De pessoas (Díon Crisóstomo 38 [55], 6, <span class=\"greek\">Ὁμήρου</span> <span class=\"greek\">ζ</span>.; SIG 717, 33; OGI 339, 90; Josefo, Vi. 11). <span class=\"greek\">ζ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «aquele que é leal a Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 22:3</a> (Musônio 37, 3, <span class=\"greek\">ζ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Διός</span>; Epicteto 2, 14, 13).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. De coisas (Diodoro Sículo 1, 73, 9, <span class=\"greek\">τ</span>. <span class=\"greek\">πολεμικῶν</span> <span class=\"greek\">ἔργων</span>; 2, 1, 4, <span class=\"greek\">ζ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀρετῆς</span>; Epicteto 2, 12, 25; 3, 24, 40; SIG 675, 27s., <span class=\"greek\">ζ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">αἱρέσεως</span>; 756, 32; Fílon, Praem. 11, <span class=\"greek\">ἀρετῆς</span>, Spec. Leg. 1, 30, Virt. 175; Josefo, C. Ap. 1, 162). <span class=\"greek\">ζ</span>. <span class=\"greek\">ἐστε</span> <span class=\"greek\">πνευμάτων</span>, «estais ávidos por possuir espíritos [isto é, dons espirituais]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:12</a>. <span class=\"greek\">ζ</span>. <span class=\"greek\">καλῶν</span> <span class=\"greek\">ἔργων</span>, «dedicado à prática de boas obras», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:14</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀγαθοῦ</span>, «do bem», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:13</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span>, «observador ardoroso da lei», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:20</a> (cf. 2Mc 4:2; Fílon, Spec. Leg. 2, 253; Josefo, Ant. 12, 271). <span class=\"greek\">ζ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">πατρικῶν</span> <span class=\"greek\">μου</span> <span class=\"greek\">παραδόσεων</span>, «zeloso das tradições de meus pais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:14</a> (Trasilo [século I d.C.] em Diógenes Laércio 9, 38: Demócrito como <span class=\"greek\">ζ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">Πυθαγορικῶν</span>; Fílon, Mos. 2, 161, <span class=\"greek\">ζ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">Αἰγυπτιακῶν</span> <span class=\"greek\">πλασμάτων</span>). Também, de preferência, no sentido de adepto entusiasta de uma pessoa ou causa (Estrabão 10, 5, 6, p. 486, <span class=\"greek\">τοῦ</span> <span class=\"greek\">Βίωνος</span> <span class=\"greek\">ζηλωτής</span>; Apiano, Bell. Civ. 2, 2 §4, <span class=\"greek\">Σύλλα</span> <span class=\"greek\">φίλος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ζ</span>.; Polieno 5, 2, 22; Diógenes Laércio 2, 113; Mêmnon [séculos I a.C./I d.C.]: 434 Fgm. 1, 35, 1 Jac., <span class=\"greek\">ζ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Λαμάχου</span> <span class=\"greek\">προαιρέσεως</span> = «do partido de L.»). Em emprego absoluto (Jâmblico, Vi. Pyth. 5, 29; Marino, Vi. Procli 38 Boiss.; Ar. 7, 3 e outros), em sentido negativo, «ciumento» (com <span class=\"greek\">ἐριστικός</span>, <span class=\"greek\">θυμικός</span>), D 3:2.</p><p class=\"entry-text\">ⓑ Com <span class=\"greek\">περί</span> introduzindo uma coisa: <span class=\"greek\">α</span>. com genitivo, 1Cl 45:1; <span class=\"greek\">β</span>. com acusativo, Pol 6:3.</p><p class=\"entry-text\">② <strong>Ultranacionalista, patriota, zelote.</strong> (<span class=\"greek\">ὁ</span>) <span class=\"greek\">ζηλωτής</span> é o epíteto de um dos Doze, chamado Simão, o Patriota (Zelote), para distingui-lo de Simão Pedro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:13</a>; GEb 34, 61 (cf. Josefo, Bell. 2, 651; 4, 160; ver <span class=\"greek\">Καναναῖος</span>. W. Farmer, <em>Maccabees, Zealots and Josephus</em>, 1956; M. Hengel, <em>Die Zeloten</em> [Herodes I a 70 d.C.], 2.ª ed., 1976; M. Smith, HTR 64, 1971, 1–19; S. Brandon, <em>Jesus and the Zealots</em>, 1967; resposta de Brandon às críticas, NTS 17, 1970/71, 453; J. Griffiths, ibid. 19, 1973, 483–89; H. Kingdon, ibid. 19, 1972, 74–81). — DELG, s.v. <span class=\"greek\">ζῆλος</span>; M-M; EDNT; TW; Sv.</p></section></article>\n"};
